preservation_command:
$ErrorActionPreference='Stop'
$workspace=(Get-Location).Path
$runRoot='results/gftd_fit297_20261107'
$privateRoot='private_data/gftd_fit297_20261107'
$archiveRoot=Join-Path $privateRoot 'failure_evidence01'
if(Test-Path -LiteralPath $archiveRoot){throw 'Failure archive already exists; refusing overwrite'}
$release=Get-Content -LiteralPath "$runRoot/execution_release.json" -Raw|ConvertFrom-Json
$partial=Get-Content -LiteralPath "$runRoot/execution.partial.json" -Raw|ConvertFrom-Json
$temp=Get-Content -LiteralPath "$runRoot/execution.partial.json.tmp" -Raw|ConvertFrom-Json
$files=[System.Collections.Generic.List[string]]::new()
foreach($property in $release.source_sha256.PSObject.Properties){$files.Add($property.Name)}
Get-ChildItem -LiteralPath $runRoot -File|Where-Object {$_.Name -like 'execution*' -or $_.Name -eq 'started.json'}|ForEach-Object {$files.Add([System.IO.Path]::GetRelativePath($workspace,$_.FullName))}
Get-ChildItem -LiteralPath $privateRoot -File|ForEach-Object {$files.Add([System.IO.Path]::GetRelativePath($workspace,$_.FullName))}
Get-ChildItem -LiteralPath "$privateRoot/initializations" -File|ForEach-Object {$files.Add([System.IO.Path]::GetRelativePath($workspace,$_.FullName))}
$entries=@(foreach($relative in $files){
  $item=Get-Item -LiteralPath $relative
  $before=(Get-FileHash -LiteralPath $relative -Algorithm SHA256).Hash.ToLower()
  $dest=Join-Path $archiveRoot $relative
  $parent=Split-Path -Parent $dest
  [System.IO.Directory]::CreateDirectory($parent)|Out-Null
  Copy-Item -LiteralPath $relative -Destination $dest
  $after=(Get-FileHash -LiteralPath $relative -Algorithm SHA256).Hash.ToLower()
  $copy=(Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash.ToLower()
  if($before -ne $after -or $before -ne $copy){throw "Snapshot changed: $relative"}
  [ordered]@{path=$relative;bytes=$item.Length;sha256=$before;archive_path=$dest;archive_sha256=$copy}
})
$sourceChecks=@(foreach($property in $release.source_sha256.PSObject.Properties){
  $actual=(Get-FileHash -LiteralPath $property.Name -Algorithm SHA256).Hash.ToLower()
  [ordered]@{path=$property.Name;expected=$property.Value;actual=$actual;matched=($actual -eq $property.Value)}
})
$diagRows=@(Get-ChildItem -LiteralPath "$privateRoot/initializations" -Filter '*.json'|Sort-Object Name|ForEach-Object{
  $detail=Get-Content -LiteralPath $_.FullName -Raw|ConvertFrom-Json
  [ordered]@{file=$_.Name;event_id=$detail.event_id;status=$detail.diagnostics.status;stage1_status=$detail.diagnostics.stage1.status;stage1_numerical_passed=$detail.diagnostics.stage1_numerical.passed;counts=$detail.diagnostics.counts;state=$detail.state}
})
$processes=@(Get-Process -Id 25564,55472 -ErrorAction SilentlyContinue|Select-Object Id,CPU,WorkingSet64)
$record=[ordered]@{
  recorded_utc=[DateTimeOffset]::UtcNow.ToString('o');action_id=$release.action_id
  purpose='Byte preservation after sole scientific process exited; no replay or science recomputation'
  release_sha256=(Get-FileHash -LiteralPath "$runRoot/execution_release.json" -Algorithm SHA256).Hash.ToLower()
  archive_root=$archiveRoot;files=$entries;source_checks=$sourceChecks
  source_count=$sourceChecks.Count;source_unchanged=(@($sourceChecks|Where-Object {-not $_.matched}).Count -eq 0)
  partial_snapshot=@{path="$runRoot/execution.partial.json";status=$partial.status;current=$partial.current;counts=$partial.counts;costs=$partial.costs;last_artifact=$partial.artifacts[-1]}
  interrupted_temp_snapshot=@{path="$runRoot/execution.partial.json.tmp";status=$temp.status;current=$temp.current;counts=$temp.counts;costs=$temp.costs;last_artifact=$temp.artifacts[-1];is_final_receipt=$false}
  durable_diagnostics=$diagRows;durable_diag_count=$diagRows.Count
  durable_state_count=@(Get-ChildItem -LiteralPath "$privateRoot/initializations" -Filter '*.npz').Count
  next_unstarted=@{mode='static';zero_based_index=41;event_id=$temp.input_identity.legal_ids[41];diag_exists=(Test-Path -LiteralPath "$privateRoot/initializations/static_041.json");proof='Traceback at line386 tail persist after static_040 detail write, before next loop iteration'}
  process_check_utc=[DateTimeOffset]::UtcNow.ToString('o');processes=$processes
  execution_json_exists=(Test-Path -LiteralPath "$runRoot/execution.json")
  error_cause='unknown';share_lock_cause='possible, not established';original_artifacts_modified=$false
}
$json=$record|ConvertTo-Json -Depth 30
[System.IO.File]::WriteAllText((Join-Path $workspace "$runRoot/failure_preservation_manifest.json"),$json+[Environment]::NewLine,[System.Text.UTF8Encoding]::new($false))
[ordered]@{archive_root=$archiveRoot;file_count=$entries.Count;bytes=($entries|Measure-Object bytes -Sum).Sum;source_count=$sourceChecks.Count;source_unchanged=$record.source_unchanged;process_count=$processes.Count;manifest_sha256=(Get-FileHash "$runRoot/failure_preservation_manifest.json" -Algorithm SHA256).Hash.ToLower();diagnostics=$diagRows.Count;states=$record.durable_state_count}|ConvertTo-Json -Compress
